106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        return withOwner(ownerId, owner ->
110	            new ResponseEntity<>(buildOwnerDto(owner), HttpStatus.OK));
111	    }
112	
113	    /**
114	     * Look up the owner identified by {@code ownerId} and, when it exists, produce the response with
115	     * {@code onFound}; when no such owner exists, short-circuit with {@code 404 NOT_FOUND}. Centralizes
116	     * the fetch-and-guard shared by the single-owner endpoints so it is written once, not copied.
117	     */
118	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> onFound) {
119	        Owner owner = this.clinicService.findOwnerById(ownerId);
120	        if (owner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return onFound.apply(owner);
