125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
130	        if (!normalizeAndValidateFields(owner)) {
131	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
132	        }
133	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
134	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
135	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
136	        }
137	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
138	        owner.setRegistrationDate(registrationDate);
139	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
140	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
141	        }
142	        owner.setIdentityKey(identityKey(owner));
143	        if (isDuplicate(owner)) {
144	            return new ResponseEntity<>(HttpStatus.CONFLICT);
145	        }
146	        if (countOwnersInCity(owner.getCity()) >= 50) {
147	            return new ResponseEntity<>(HttpStatus.CONFLICT);
148	        }
149	        assignRegistrationAttributes(owner);
150	        this.clinicService.saveOwner(owner);
151	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
152	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
153	        HttpHeaders headers = new HttpHeaders();
154	        headers.setLocation(UriComponentsBuilder.newInstance()
155	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
156	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
157	    }
158	
159	    /**
160	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
161	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
162	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
163	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
164	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
165	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
166	     */
167	    private boolean normalizeAndValidateFields(Owner owner) {
168	        String address = normalizeAddress(owner.getAddress());
169	        if (address.isEmpty()) {
170	            return false;
171	        }
172	        owner.setAddress(address);
173	        if (owner.getEmail() != null) {
174	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
175	            if (!EMAIL_PATTERN.matcher(email).matches()) {
176	                return false;
177	            }
178	            owner.setEmail(email);
179	        }
180	        if (!isPostcodeValidForCity(owner)) {
181	            return false;
182	        }
183	        String telephone = normalizeTelephone(owner.getTelephone());
184	        if (telephone == null) {
185	            return false;
186	        }
187	        owner.setTelephone(telephone);
188	        return true;
189	    }
190	
191	    /**
192	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
193	     * computed against the owner population rather than carried on the owner itself (currently the
194	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
195	     * listing intentionally omits these flags.
196	     */
197	    private OwnerDto buildOwnerDto(Owner owner) {
198	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
199	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
200	        return ownerDto;
