214	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
215	        String email = ownerFieldsDto.getEmail();
216	        if (email != null) {
217	            email = email.trim().toLowerCase(Locale.ROOT);
218	            if (!EMAIL_PATTERN.matcher(email).matches()) {
219	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
220	            }
221	        }
222	        currentOwner.setEmail(email);
223	        this.clinicService.saveOwner(currentOwner);
