186	        this.membershipNumber = membershipNumber;
187	    }
188	
189	    /**
190	     * The owner's numeric membership level, derived on creation: it starts at 1, gains 1 when an
191	     * email is present, gains 1 when {@link #namesakeCount} is 0, and is capped at 3 (level 4 is
192	     * reserved for tenure).
193	     */
194	    @Transient
195	    public Integer getMembershipLevel() {
196	        int level = 1;
197	        if (this.email != null && !this.email.isBlank()) {
198	            level++;
199	        }
200	        if (this.namesakeCount != null && this.namesakeCount == 0) {
201	            level++;
202	        }
203	        return Math.min(level, 3);
204	    }
205	
206	    /**
207	     * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
208	     * present, otherwise {@code "PHONE"}.
209	     */
210	    @Transient
211	    public String getContactPreference() {
212	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
213	    }
214	
215	    /**
216	     * The owner's age band, derived on read from the {@link #birthDate} relative to the
217	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
218	     * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
219	     * date to measure against) is available.
220	     */
221	    @Transient
222	    public String getAgeBand() {
223	        if (this.birthDate == null || this.registrationDate == null) {
224	            return null;
225	        }
226	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
227	        if (age < 18) {
228	            return "MINOR";
229	        }
230	        if (age < 65) {
231	            return "ADULT";
232	        }
233	        return "SENIOR";
234	    }
235	
236	    /**
237	     * The single Luhn check digit (0-9) computed over the decimal digits contained in the
238	     * {@link #customerCode}, derived on read.
239	     */
240	    @Transient
241	    public Integer getCheckDigit() {
242	        return luhnCheckDigit(this.customerCode);
243	    }
244	
245	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
246	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
247	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
248	        "NSW", new int[] {2000, 2099},
249	        "VIC", new int[] {3000, 3099},
250	        "QLD", new int[] {4000, 4099});
251	
252	    /**
253	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
254	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
255	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
256	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
257	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
258	     */
259	    @Transient
260	    public String getRegion() {
261	        String byPostcode = regionForPostcode(this.postcode);
262	        if (byPostcode != null) {
263	            return byPostcode;
264	        }
265	        if ("Sydney".equals(this.city)) {
266	            return "NSW";
267	        }
268	        if ("Melbourne".equals(this.city)) {
269	            return "VIC";
270	        }
271	        if ("Brisbane".equals(this.city)) {
272	            return "QLD";
273	        }
274	        return "UNKNOWN";
275	    }
276	
277	    /**
278	     * The owner's locality, derived on read from the region-and-hash {@link #getCustomerCode()
279	     * customer code}: the region segment before the first '-' of the customer code
280	     * ('<REGION>-<HASH8>'). Falls back to the owner's {@link #getRegion() region} when no customer
281	     * code has been assigned yet.
282	     */
283	    @Transient
284	    public String getLocality() {
285	        if (this.customerCode != null) {
286	            int dash = this.customerCode.indexOf('-');
287	            if (dash > 0) {
288	                return this.customerCode.substring(0, dash);
289	            }
290	        }
291	        return getRegion();
292	    }
293	
294	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
295	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
296	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
297	    public static int[] postcodeRangeForRegion(String region) {
298	        return REGION_POSTCODE_RANGES.get(region);
299	    }
300	
301	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
302	     *  absent, not a 4-digit value, or in no known range. */
303	    private static String regionForPostcode(String postcode) {
304	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
305	            return null;
306	        }
307	        int value = Integer.parseInt(postcode);
308	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
309	            int[] range = entry.getValue();
310	            if (value >= range[0] && value <= range[1]) {
311	                return entry.getKey();
312	            }
313	        }
314	        return null;
315	    }
316	
317	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
318	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
319	     *  digit-free value yields {@code 0}. */
320	    private static int luhnCheckDigit(String value) {
321	        int sum = 0;
322	        boolean doubling = true;
323	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
324	            char c = value.charAt(i);
325	            if (c < '0' || c > '9') {
326	                continue;
327	            }
328	            int digit = c - '0';
329	            if (doubling) {
330	                digit *= 2;
331	                if (digit > 9) {
332	                    digit -= 9;
333	                }
334	            }
335	            sum += digit;
336	            doubling = !doubling;
337	        }
338	        return (10 - (sum % 10)) % 10;
339	    }
340	
341	    protected Set<Pet> getPetsInternal() {
342	        if (this.pets == null) {
343	            this.pets = new HashSet<>();
344	        }
345	        return this.pets;
346	    }
347	
348	    protected void setPetsInternal(Set<Pet> pets) {
349	        this.pets = pets;
350	    }
351	
352	    public List<Pet> getPets() {
353	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
354	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
355	        return Collections.unmodifiableList(sortedPets);
356	    }
357	
358	    public void setPets(List<Pet> pets) {
359	        this.pets = new HashSet<>(pets);
360	    }
361	
362	    public void addPet(Pet pet) {
363	        getPetsInternal().add(pet);
364	        pet.setOwner(this);
365	    }
366	
367	    /**
368	     * Return the Pet with the given name, or null if none found for this Owner.
369	     *
370	     * @param name to test
371	     * @return true if pet name is already in use
372	     */
373	    public Pet getPet(String name) {
374	        return getPet(name, false);
375	    }
376	
377	    /**
378	     * Return the Pet with the given name, or null if none found for this Owner.
379	     *
380	     * @param name to test
381	     * @return true if pet name is already in use
382	     */
383	    public Pet getPet(String name, boolean ignoreNew) {
384	        name = name.toLowerCase();
385	        for (Pet pet : getPetsInternal()) {
386	            if (!ignoreNew || !pet.isNew()) {
387	                String compName = pet.getName();
388	                compName = compName.toLowerCase();
389	                if (compName.equals(name)) {
390	                    return pet;
391	                }
392	            }
393	        }
394	        return null;
395	    }
396	
397	    public Pet getPet(Integer petId) {
398	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
399	    }
400	
401	    @Override
402	    public String toString() {
403	        return new ToStringCreator(this)
404	
405	            .append("id", this.getId())
406	            .append("new", this.isNew())
407	            .append("lastName", this.getLastName())
408	            .append("firstName", this.getFirstName())
409	            .append("address", this.address)
410	            .append("city", this.city)
411	            .append("telephone", this.telephone)
412	            .toString();
413	    }
414	}
